using System.ComponentModel;
using System.Text;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap a REST API via HttpClient.
/// Non-static class — services are injected via the constructor.
/// </summary>
[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("List all resources from the API. Returns JSON array.")]
    public async Task<string> ListResources(
        [Description("Maximum number of items to return (1-100)")] int limit = 20,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing resources (limit={Limit})", limit);
        var response = await httpClient.GetAsync($"/posts?_limit={limit}", cancellationToken);
        response.EnsureSuccessStatusCode();
        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }

    [McpServerTool, Description("Get a single resource by its numeric ID.")]
    public async Task<string> GetResource(
        [Description("The numeric ID of the resource to retrieve")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Getting resource {Id}", id);
        var response = await httpClient.GetAsync($"/posts/{id}", cancellationToken);
        response.EnsureSuccessStatusCode();
        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }

    [McpServerTool(Destructive = false, ReadOnly = false),
     Description("Create a new resource. Returns the created object as JSON.")]
    public async Task<string> CreateResource(
        [Description("Title of the new resource")] string title,
        [Description("Body content of the new resource")] string body,
        [Description("Author user ID")] int userId = 1,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating resource for user {UserId}", userId);
        var payload = JsonSerializer.Serialize(new { title, body, userId });
        var content = new StringContent(payload, Encoding.UTF8, "application/json");
        var response = await httpClient.PostAsync("/posts", content, cancellationToken);
        response.EnsureSuccessStatusCode();
        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }

    [McpServerTool(Destructive = true),
     Description("Delete a resource by ID. Returns confirmation message.")]
    public async Task<string> DeleteResource(
        [Description("The numeric ID of the resource to delete")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Deleting resource {Id}", id);
        var response = await httpClient.DeleteAsync($"/posts/{id}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return $"Resource {id} deleted successfully.";
    }
}

